     1	import { Inject, Injectable } from '@nestjs/common';
     2	import { BriefService } from '../brief/brief.service';
     3	import { ChannelCatalogService } from '../channel-catalog/channel-catalog.service';
     4	import { ResultEntity } from './entities/result.entity';
     5	import { RESULT_REPOSITORY, ResultRepository } from './ports/result.repository';
     6	import { CHANNEL_MATCHER, ChannelMatcher } from './ports/channel-matcher';
     7	import { ScoringService } from './scoring/scoring.service';
     8	import { ResultResponseDto } from './dto/result-response.dto';
     9	
    10	@Injectable()
    11	export class DiscoveryService {
    12	  constructor(
    13	    private readonly briefService: BriefService,
    14	    private readonly catalog: ChannelCatalogService,
    15	    @Inject(CHANNEL_MATCHER) private readonly matcher: ChannelMatcher,
    16	    @Inject(RESULT_REPOSITORY) private readonly results: ResultRepository,
    17	    private readonly scoring: ScoringService,
    18	  ) {}
    19	
    20	  async discover(briefId: string): Promise<ResultResponseDto[]> {
    21	    const brief = await this.briefService.findById(briefId);
    22	    const candidates = await this.catalog.findByAudienceSegments(brief.audienceSegments);
    23	    const scored = await this.matcher.match(brief, candidates);
    24	
    25	    const entities = scored.map((candidate) => {
    26	      const result = new ResultEntity();
    27	      result.briefId = brief.id;
    28	      result.channelType = candidate.channelType;
    29	      result.name = candidate.name;
    30	      result.url = candidate.url;
    31	      result.whyItFits = candidate.whyItFits;
    32	      result.reachScore = candidate.scores.reach;
    33	      result.receptivenessScore = candidate.scores.receptiveness;
    34	      result.warmthScore = candidate.scores.warmth;
    35	      result.confidenceTotal = this.scoring.computeConfidence(candidate.scores);
    36	      result.source = candidate.source;
    37	      return result;
    38	    });
    39	
    40	    const saved = await this.results.saveMany(entities);
    41	    return this.toRankedResponse(saved);
    42	  }
    43	
    44	  async findByBriefId(briefId: string): Promise<ResultResponseDto[]> {
    45	    const results = await this.results.findByBriefId(briefId);
    46	    return this.toRankedResponse(results);
    47	  }
    48	
    49	  private toRankedResponse(results: ResultEntity[]): ResultResponseDto[] {
    50	    const sorted = [...results].sort((a, b) => b.confidenceTotal - a.confidenceTotal);
    51	    const topConfidence = sorted[0]?.confidenceTotal;
    52	    return sorted.map((r) => ResultResponseDto.from(r, topConfidence));
    53	  }
    54	}
