     1	/**
     2	 * PRODUCT_SPEC.md defines channel_type as: discord | reddit | facebook_group |
     3	 * company | individual. The reused static catalog (backend/communities.json)
     4	 * covers more platforms than that (Slack, LinkedIn, Twitter/X, Newsletter,
     5	 * Meetup, Forum), so the enum is extended to a superset rather than forcing
     6	 * a lossy mapping onto 5 values. `company`/`individual` are kept for results
     7	 * OpenAI surfaces outside the static catalog (no company/individual data
     8	 * exists in communities.json).
     9	 */
    10	export enum ChannelType {
    11	  DISCORD = 'discord',
    12	  REDDIT = 'reddit',
    13	  FACEBOOK_GROUP = 'facebook_group',
    14	  SLACK = 'slack',
    15	  LINKEDIN = 'linkedin',
    16	  TWITTER = 'twitter',
    17	  NEWSLETTER = 'newsletter',
    18	  MEETUP = 'meetup',
    19	  FORUM = 'forum',
    20	  COMPANY = 'company',
    21	  INDIVIDUAL = 'individual',
    22	}
    23	
    24	const PLATFORM_TO_CHANNEL_TYPE: Record<string, ChannelType> = {
    25	  discord: ChannelType.DISCORD,
    26	  reddit: ChannelType.REDDIT,
    27	  facebook: ChannelType.FACEBOOK_GROUP,
    28	  slack: ChannelType.SLACK,
    29	  linkedin: ChannelType.LINKEDIN,
    30	  'twitter/x': ChannelType.TWITTER,
    31	  twitter: ChannelType.TWITTER,
    32	  newsletter: ChannelType.NEWSLETTER,
    33	  meetup: ChannelType.MEETUP,
    34	  forum: ChannelType.FORUM,
    35	};
    36	
    37	export function channelTypeFromPlatform(platform: string): ChannelType {
    38	  return PLATFORM_TO_CHANNEL_TYPE[platform.toLowerCase()] ?? ChannelType.FORUM;
