    13	
    14	const REFINEMENT_MIN_ATTEMPTS = 3;
    15	const CONVERTED_OUTCOMES = new Set([AttemptOutcome.SIGNED_UP, AttemptOutcome.PAYING]);
    16	const RESPONDED_OUTCOMES = new Set([
    17	  AttemptOutcome.INTERESTED,
    18	  AttemptOutcome.SIGNED_UP,
    19	  AttemptOutcome.PAYING,
    20	]);
    21	
    22	@Injectable()
    23	export class DashboardService {
    24	  constructor(
    25	    @Inject(ATTEMPT_REPOSITORY) private readonly attempts: AttemptRepository,
    26	  ) {}
    27	
    28	  async build(): Promise<DashboardResponseDto> {
    29	    const attempts = await this.attempts.findAll();
    30	    return DashboardService.compute(attempts);
    31	  }
    32	
    33	  /** Pure — takes attempts (with `result` relation loaded), returns the full dashboard payload. */
    34	  static compute(attempts: AttemptEntity[]): DashboardResponseDto {
    35	    const totalAttempts = attempts.length;
    36	    const responded = attempts.filter((a) => RESPONDED_OUTCOMES.has(a.outcome)).length;
    37	    const signUps = attempts.filter((a) => CONVERTED_OUTCOMES.has(a.outcome)).length;
    38	    const revenue = attempts
    39	      .filter((a) => a.outcome === AttemptOutcome.PAYING)
    40	      .reduce((sum, a) => sum + Number(a.revenue ?? 0), 0);
    41	
    42	    return {
    43	      totalAttempts,
    44	      responseRate: totalAttempts > 0 ? round(responded / totalAttempts) : 0,
    45	      signUps,
    46	      revenue,
    47	      growthOverTime: buildGrowthOverTime(attempts),
    48	      funnel: buildFunnel(attempts),
    49	      performanceByChannel: buildChannelPerformance(attempts),
    50	      recentAttempts: buildRecentAttempts(attempts),
    51	      refinementInsight:
    52	        totalAttempts >= REFINEMENT_MIN_ATTEMPTS ? buildRefinementInsight(attempts) : null,
    53	    };
    54	  }
    55	}
    56	
    57	function round(value: number): number {
    58	  return Math.round(value * 100) / 100;
    59	}
    60	
    61	function buildGrowthOverTime(attempts: AttemptEntity[]): DailyGrowthPoint[] {
    62	  const byDate = new Map<string, DailyGrowthPoint>();
    63	  for (const attempt of attempts) {
    64	    const date = attempt.loggedAt.toISOString().slice(0, 10);
    65	    const point = byDate.get(date) ?? { date, signups: 0, revenue: 0 };
    66	    if (CONVERTED_OUTCOMES.has(attempt.outcome)) point.signups += 1;
    67	    if (attempt.outcome === AttemptOutcome.PAYING) point.revenue += Number(attempt.revenue ?? 0);
    68	    byDate.set(date, point);
    69	  }
    70	  return [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date));
    71	}
