    74	  const interested = attempts.filter((a) => RESPONDED_OUTCOMES.has(a.outcome)).length;
    75	  const signedUp = attempts.filter((a) => CONVERTED_OUTCOMES.has(a.outcome)).length;
    76	  const paying = attempts.filter((a) => a.outcome === AttemptOutcome.PAYING).length;
    77	
    78	  return [
    79	    { stage: 'attempts', count: attempts.length },
    80	    { stage: 'interested', count: interested },
    81	    { stage: 'signed_up', count: signedUp },
    82	    { stage: 'paying', count: paying },
    83	  ];
    84	}
    85	
    86	function buildChannelPerformance(attempts: AttemptEntity[]): ChannelPerformance[] {
    87	  const byChannel = new Map<ChannelType, AttemptEntity[]>();
    88	  for (const attempt of attempts) {
    89	    const channelType = attempt.result?.channelType;
    90	    if (!channelType) continue;
    91	    const bucket = byChannel.get(channelType) ?? [];
    92	    bucket.push(attempt);
    93	    byChannel.set(channelType, bucket);
    94	  }
    95	
    96	  return [...byChannel.entries()].map(([channelType, bucket]) => {
    97	    const responded = bucket.filter((a) => RESPONDED_OUTCOMES.has(a.outcome)).length;
    98	    const signups = bucket.filter((a) => CONVERTED_OUTCOMES.has(a.outcome)).length;
    99	    const revenue = bucket
   100	      .filter((a) => a.outcome === AttemptOutcome.PAYING)
   101	      .reduce((sum, a) => sum + Number(a.revenue ?? 0), 0);
   102	    return {
   103	      channelType,
   104	      attempts: bucket.length,
   105	      responseRate: round(responded / bucket.length),
   106	      signups,
   107	      revenue,
   108	    };
   109	  });
   110	}
   111	
   112	function buildRecentAttempts(attempts: AttemptEntity[]): RecentAttempt[] {
   113	  return attempts.slice(0, 20).map((a) => ({
   114	    id: a.id,
   115	    resultId: a.resultId,
   116	    channelType: a.result?.channelType,
   117	    outcome: a.outcome,
   118	    loggedAt: a.loggedAt,
   119	  }));
   120	}
   121	
   122	/**
   123	 * Rule-based (v1, not ML) — same philosophy as ScoringService. Compares
   124	 * conversion rate of the best- vs worst-performing channel type, in plain
   125	 * language, per PRODUCT_SPEC.md's example: "communities are converting at
   126	 * X% vs Y% for cold email". PRODUCT_SPEC.md's AC only requires 3+ total
   127	 * logged attempts (checked by the caller) — no per-channel minimum.
   128	 */
   129	function buildRefinementInsight(attempts: AttemptEntity[]): string | null {
   130	  const performance = buildChannelPerformance(attempts);
   131	  if (performance.length < 2) return null;
   132	
   133	  const sorted = [...performance].sort(
   134	    (a, b) => b.signups / b.attempts - a.signups / a.attempts,
   135	  );
   136	  const best = sorted[0];
   137	  const worst = sorted[sorted.length - 1];
   138	  const bestRate = Math.round((best.signups / best.attempts) * 100);
   139	  const worstRate = Math.round((worst.signups / worst.attempts) * 100);
   140	
   141	  if (bestRate === worstRate) return null;
   142	
   143	  return `${best.channelType} is converting at ${bestRate}% vs ${worstRate}% for ${worst.channelType} — future suggestions are weighted toward ${best.channelType}.`;
   144	}

